create schema auth;create schema private;
create role anon;create role authenticated;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid;$$;
grant usage on schema public,private,auth to authenticated;
create table public.accounts(id uuid primary key default gen_random_uuid(),auth_user_id uuid unique,display_name text default '',role text check(role in ('admin','shaykh','student')),active boolean default true);
create function private.is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.accounts where auth_user_id=(select auth.uid()) and active and role='admin');$$;
create function private.is_staff() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.accounts where auth_user_id=(select auth.uid()) and active and role in ('admin','shaykh'));$$;
alter table public.accounts enable row level security;create policy accounts_read on public.accounts for select to authenticated using(auth_user_id=(select auth.uid()) or private.is_admin());grant select on public.accounts to authenticated;
create table public.workspace_records(kind text not null,id uuid primary key default gen_random_uuid(),payload jsonb not null default '{}',created_at timestamptz default now());
alter table public.workspace_records enable row level security;
create policy workspace_read on public.workspace_records for select to authenticated using(private.is_admin() or private.is_staff() and (payload->>'ownerId'=auth.uid()::text or coalesce(payload->>'ownerId','')=''));
create policy workspace_write on public.workspace_records for all to authenticated using(private.is_admin() or private.is_staff() and payload->>'ownerId'=auth.uid()::text) with check(private.is_admin() or private.is_staff() and payload->>'ownerId'=auth.uid()::text);
grant select,insert,update,delete on public.workspace_records to authenticated;
create table public.certificates(id uuid primary key default gen_random_uuid(),issuer_id uuid,status text default 'draft');alter table public.certificates enable row level security;create policy cert_write on public.certificates for all to authenticated using(private.is_staff()) with check(private.is_staff());grant select,insert,update on public.certificates to authenticated;
create table public.certificate_snapshots(id uuid primary key default gen_random_uuid(),certificate_id uuid,content jsonb);
create table private.application_backups(id uuid primary key default gen_random_uuid(),purpose text,snapshot jsonb);
create function private.finalize_certificate(target uuid,snapshot jsonb) returns text language plpgsql security definer set search_path='' as $$begin if auth.uid() is null then raise exception 'Authentication required';end if;update public.certificates set status='finalized' where id=target;insert into public.certificate_snapshots(certificate_id,content) values(target,snapshot);return 'test';end;$$;
create function private.full_application_backup() returns jsonb language plpgsql security definer set search_path='' as $$begin if not private.is_admin() then raise exception 'Admin required';end if;return jsonb_build_object('accounts',(select jsonb_agg(to_jsonb(a)) from public.accounts a));end;$$;
create function private.restore_application_backup(data jsonb,overwrite boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$begin if not private.is_admin() then raise exception 'Admin required';end if;insert into public.accounts select * from jsonb_populate_recordset(null::public.accounts,data->'accounts') on conflict(id) do nothing;return jsonb_build_object('success',true);end;$$;
insert into public.accounts(id,auth_user_id,display_name,role) values ('00000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Admin','admin'),('00000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','Shaykh','shaykh'),('00000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000003','Other shaykh','shaykh'),('00000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000004','Student','student');
